SELECT CASE WHEN salary >= 154000 THEN 'high' WHEN salary >= 45000 THEN 'mid' ELSE 'low' END AS salary_bucket, DATE_TRUNC('MONTH', hire_date) AS hire_month, MAX(salary) AS max_salary, ROUND((100 * SUM(CASE WHEN job_title = 'Director' THEN 1 ELSE 0 END)) / COUNT(*), 1) AS pct_director FROM employees WHERE UPPER(full_name) LIKE '%ENR%' GROUP BY CASE WHEN salary >= 154000 THEN 'high' WHEN salary >= 45000 THEN 'mid' ELSE 'low' END, DATE_TRUNC('MONTH', hire_date) HAVING MAX(salary) > 117000 ORDER BY hire_month;
